# Bash completion for adtool. Maintainer: Carlos Andrade <carlos@perezandrade.com>
# Generated by 'adtool completion bash'; do not edit, change adtool instead.
# Options come from 'adtool __flags' and names from 'adtool __complete'.
# Bash 3.2 compatible.
_adtool_complete() {
  local bin=${COMP_WORDS[0]} cur prev cmd flag="" spec opt val i w
  cur=${COMP_WORDS[COMP_CWORD]}
  prev=${COMP_WORDS[COMP_CWORD-1]:-}
  COMPREPLY=()

  # '=' is a word break: "--count=ou" arrives as "--count" "=" "ou"
  if [[ $cur == "=" ]]; then
    cur=""; flag=$prev
  elif [[ $prev == "=" ]]; then
    flag=${COMP_WORDS[COMP_CWORD-2]:-}
  elif [[ $prev == -* ]]; then
    flag=$prev
  fi

  if (( COMP_CWORD == 1 )); then
    _adtool_emit "$("$bin" __flags top 2>/dev/null)" "$cur"
    return 0
  fi

  cmd=${COMP_WORDS[1]}
  case $cmd in
    u) cmd=user ;; g) cmd=group ;; c|pc) cmd=computer ;; pw) cmd=password ;;
  esac
  case $cmd in
    user|group|computer|password|completion) ;;
    *) return 0 ;;
  esac
  if [[ $cmd == password || $cmd == completion ]]; then
    (( COMP_CWORD == 2 )) && _adtool_emit "$("$bin" __flags "$cmd" 2>/dev/null)" "$cur"
    return 0
  fi

  spec=$("$bin" __flags "$cmd" 2>/dev/null)

  # a value for the previous option?
  if [[ -n $flag ]]; then
    while IFS='|' read -r opt val _; do
      [[ $opt == "$flag" ]] || continue
      case $val in
        @dept)  _adtool_names depts "$cur"; return 0 ;;
        @title) _adtool_names titles "$cur"; return 0 ;;
        '#')    return 0 ;;
        =*)     if [[ $prev == "=" || ${COMP_WORDS[COMP_CWORD]} == "=" ]]; then
                  for w in $(printf '%s' "${val#=}" | tr , ' '); do
                    [[ $w == "$cur"* ]] && COMPREPLY[${#COMPREPLY[@]}]=$w
                  done
                  return 0
                fi ;;
      esac
    done <<<"$spec"
  fi

  if [[ $cur == -* ]]; then
    _adtool_emit "$spec" "$cur"
    return 0
  fi

  # a name: logins for an account action, otherwise what the command searches
  local action=0 kind=users
  for (( i = 2; i < COMP_CWORD; i++ )); do
    case ${COMP_WORDS[i]} in -r|--reset|-l|--lock|-u|--unlock) action=1 ;; esac
  done
  case $cmd in group) kind=groups ;; computer) kind=computers ;; esac
  if [[ -z $cur && $action == 0 ]]; then
    _adtool_emit "$spec" "$cur"
  else
    _adtool_names "$kind" "$cur"
  fi
  return 0
}

# _adtool_emit <spec lines> <prefix>: the options that start with prefix
_adtool_emit() {
  local opt
  while IFS='|' read -r opt _; do
    [[ -n $opt && $opt == "$2"* ]] && COMPREPLY[${#COMPREPLY[@]}]=$opt
  done <<<"$1"
}

# _adtool_names <kind> <prefix>: directory names, shell-quoted
_adtool_names() {
  local line p=${2#[\"\']}
  while IFS= read -r line; do
    [[ -n $line ]] && COMPREPLY[${#COMPREPLY[@]}]=$(printf '%q' "$line")
  done < <("${COMP_WORDS[0]}" __complete "$1" "$p" 2>/dev/null)
}
complete -F _adtool_complete adtool
